func TestNativeFullFailsDuringActualFlushAndStillCloses(t *testing.T) {
    target, err := os.OpenFile("/dev/full", os.O_WRONLY, 0)
    if err != nil { t.Fatal("dedicated Linux /dev/full fixture unavailable", err) }
    // This payload fits entirely inside the specified 4096-byte buffer, so the
    // real ENOSPC arises when flushing, not by simulating a filesystem failure.
    err = Export(target, []string{"fits in the buffer"})
    if !errors.Is(err, syscall.ENOSPC) { t.Fatal("native flush ENOSPC was not retained", err) }
    if _, err = target.Write([]byte("closed?")); !errors.Is(err, os.ErrClosed) {
        target.Close()
        t.Fatal("native failed destination was not closed", err)
    }
}

func TestGoStringBytesRemainOpaqueAtFunctionBoundary(t *testing.T) {
    records := []string{string([]byte{0, 255, 13}), "tail"}
    want := []byte{0, 255, 13, '\n', 't', 'a', 'i', 'l', '\n'}
    path := filepath.Join(t.TempDir(), "opaque export.bin")
    target, err := os.Create(path)
    if err != nil { t.Fatal(err) }
    if err = Export(target, records); err != nil { t.Fatal(err) }
    actual, err := os.ReadFile(path)
    if err != nil || !bytes.Equal(actual, want) { t.Fatal("function normalized Go string bytes", err, actual) }
}

