extern int list_names(const char *path);
static int interrupted=0, real_calls=0;
ssize_t read_dir_batch(int fd, void *buffer,size_t size) {
    if(!interrupted) { interrupted=1; errno=EINTR; return -1; }
    if(size<280 || size>512) { errno=EINVAL; return -1; }
    if(getenv("OPSFORGE_DIR_FAULT") && real_calls>=1) { errno=EIO; return -1; }
    real_calls++;
    return syscall(SYS_getdents64,fd,buffer,size);
}
static int count_fds(void) {
    DIR *d=opendir("/proc/self/fd"); if(!d) return -1;
    int count=0; while(readdir(d)) count++;
    closedir(d); return count;
}
int main(int argc,char **argv) {
    if(argc!=2) return 99;
    int before=count_fds(); if(before<0) return 98;
    int result=list_names(argv[1]);
    if(fflush(stdout)) result=1;
    int after=count_fds();
    fprintf(stderr,"GUARD fds=%d calls=%d\n",after-before,real_calls);
    if(after!=before) return 97;
    return result?1:0;
}

